 const clone=x=>JSON.parse(JSON.stringify(x)),hex=a=>Array.from(new Uint8Array(a),n=>n.toString(16).padStart(2,'0')).join(''),bytes=s=>new Uint8Array(s.match(/../g).map(x=>parseInt(x,16)));
 function fresh(){return {schema:1,revision:0,players:{},rates:{}}}
 function validateSecurity(s){if(s?.minutes!==undefined&&![1,3,5,10,15,30,60].includes(s.minutes))throw Error('ロック時間が不正です');if(!s||s.schema!==1||!Number.isSafeInteger(s.revision)||s.revision<0||!s.players||Array.isArray(s.players)||!s.rates||Array.isArray(s.rates))throw Error('保護設定が不正です。上書きせず停止しました。');const valid=v=>v&&v.algorithm==='PBKDF2-SHA256'&&v.iterations===ITERATIONS&&/^[a-f0-9]{32}$/.test(v.salt)&&/^[a-f0-9]{64}$/.test(v.hash)&&typeof v.version==='string'&&v.version.length<=80&&(v.policy===undefined||['digits4-10','teacher-digits6-64'].includes(v.policy));for(const [id,v]of Object.entries(s.players)){if(!/^[a-zA-Z0-9_-]{1,80}$/.test(id)||['__proto__','constructor','prototype'].includes(id)||!valid(v))throw Error('本人用の保護設定が不正です。');}if(!!s.admin!==!!s.recovery||s.admin&&!valid(s.admin)||s.recovery&&!valid(s.recovery))throw Error('先生用の保護設定が不正です。');for(const [id,r]of Object.entries(s.rates)){if(!/^(teacher|recovery|player:[a-zA-Z0-9_-]{1,80})$/.test(id)||!r||!Number.isSafeInteger(r.fails)||r.fails<0||r.fails>100000||!Number.isSafeInteger(r.until)||r.until<0||r.until>1e14)throw Error('誤入力制限が不正です。');}return clone(s)}
 sanitizeBackup=raw=>{const result=original.sanitize(raw);if(raw.security!==undefined)result.security=validateSecurity(raw.security);return result};
 function security(){return state.security?validateSecurity(state.security):fresh()}
 function verifierFor(s,key){return key==='teacher'?s.admin:key==='recovery'?s.recovery:s.players[key.replace(/^player:/,'')]}
 function hasPlayer(id=state.current){try{return id==='guest'?state.current==='guest'&&playerChosen:!!authenticated&&authenticated.id===id&&playerChosen&&!locked&&security().players[id]?.version===authenticated.version}catch{return false}}
