 function storedSecurity(){const mirror=localStorage.getItem(PROTECTION);if(mirror)return validateSecurity(JSON.parse(mirror));const raw=localStorage.getItem(KEY);if(!raw)return fresh();const parsed=JSON.parse(raw);return parsed.security?validateSecurity(parsed.security):fresh()}
 function persist(next){const clean={...next,current:next.current==='guest'?next.players.find(p=>p.id!=='guest')?.id:next.current,players:next.players.filter(p=>p.id!=='guest')};if(!clean.players.length)throw Error('登録済みプレイヤーを1人以上残してください。');const previous=localStorage.getItem(PROTECTION);localStorage.setItem(PROTECTION,JSON.stringify(next.security));try{localStorage.setItem(KEY,JSON.stringify(clean))}catch(error){try{if(previous===null)localStorage.removeItem(PROTECTION);else localStorage.setItem(PROTECTION,previous)}catch{}throw error}state=next;return next}
 async function transaction(fn){const run=async()=>{const task=async()=>{const expected=security().revision;if(storedSecurity().revision!==expected)throw Error('別の画面で保護設定が変わりました。開き直してください。');const next=clone(state);next.security=security();await fn(next);if(storedSecurity().revision!==expected)throw Error('別の画面で設定が変わりました。やり直してください。');next.security.revision++;validateSecurity(next.security);try{return persist(next)}catch(e){throw Error('保存できませんでした。変更前の記録と保護設定を保持しています。空き容量を確認してください。')}};return navigator.locks? navigator.locks.request(KEY+'-security',task):task()};const p=queue.then(run,run);queue=p.catch(()=>{});return p}
 async function derive(password,salt){if(!globalThis.crypto?.subtle)throw Error('安全なパスワード処理が使えません。HTTPS対応ブラウザで開いてください。');const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);return hex(await crypto.subtle.deriveBits({name:'PBKDF2',salt:bytes(salt),iterations:ITERATIONS,hash:'SHA-256'},key,256))}
