 async function check(key,password){const disk=storedSecurity();if(disk.revision!==security().revision)state.security=disk;const s=security(),v=verifierFor(s,key),r=s.rates[key]||{fails:0,until:0};if(r.until>Date.now())throw Error('あと'+Math.ceil((r.until-Date.now())/1000)+'秒待ってください。');if(!v)throw Error('先生に最初のパスワードを設定してもらってください。');const got=await derive(password,v.salt);let diff=0;for(let i=0;i<got.length;i++)diff|=got.charCodeAt(i)^v.hash.charCodeAt(i);await transaction(next=>{if(verifierFor(next.security,key)?.version!==v.version)throw Error('設定が変わりました。やり直してください。');const currentRate=next.security.rates[key]||{fails:0,until:0};if(currentRate.until>Date.now())throw Error('あと'+Math.ceil((currentRate.until-Date.now())/1000)+'秒待ってください。');if(diff){const n=currentRate.fails+1;next.security.rates[key]={fails:n>=5?0:n,until:n>=5?Date.now()+30000:0}}else delete next.security.rates[key]});if(diff)throw Error(r.fails+1>=5?'パスワードが違います。しばらく待ってから再入力してください。':'パスワードが違います。');return v.version}
 function passwordFields(id,label,min=4,again=false){const pin=again&&min===4,admin=again&&min===6,attrs=admin?'inputmode="numeric" pattern="[0-9]{6,64}" minlength="6" maxlength="128"':pin?'inputmode="numeric" pattern="[0-9]{4,10}" minlength="4" maxlength="128"':`maxlength="128" ${again?`minlength="${min}"`:''}`;return `<label for="${id}">${label}${again?(pin?'（数字4〜10桁）':admin?'（数字6〜64桁）':`（${min}〜128文字）`):''}</label><div class="passwordRow"><input id="${id}" type="password" required ${attrs} autocomplete="${again?'new-password':'current-password'}"><button type="button" data-show="${id}" aria-label="${label}を表示" aria-pressed="false">表示</button></div>${again?`<label for="${id}Again">確認のためもう一度</label><input id="${id}Again" type="password" required ${attrs} autocomplete="new-password">`:''}`}
 const isPin=value=>typeof value==='string'&&value.length>=4&&value.length<=10&&!/[^0-9]/.test(value);
 function newPassword(id,min=4){const value=$('#'+id).value;if(min===4&&!isPin(value))throw Error('数字4〜10桁で入力してください。');if(min===6&&(value.length<6||value.length>64||/[^0-9]/.test(value)))throw Error('数字6〜64桁で入力してください。');if(value!==$('#'+id+'Again').value)throw Error('確認用パスワードが一致しません。');return value}
 function runForm(id,fn){const form=$('#'+id),ticket=epoch;const waitKey=id==='playerLogin'?'player:'+state.current:id==='teacherLogin'?'teacher':null;if(waitKey){const tick=()=>{if(!form.isConnected){clearInterval(clock);return}const until=storedSecurity().rates[waitKey]?.until||0;if(until>Date.now())form.querySelector('[role=status]').textContent='あと'+Math.ceil((until-Date.now())/1000)+'秒待ってください。'};const clock=setInterval(tick,500);tick();}form.querySelectorAll('[pattern]').forEach(input=>{const error=input.pattern==='[0-9]{6,64}'?'数字6〜64桁で入力してください。':'数字4〜10桁で入力してください。';input.oninvalid=()=>input.setCustomValidity(error);input.oninput=()=>input.setCustomValidity('');input.onpaste=e=>{const pasted=e.clipboardData?.getData('text');if(pasted!==undefined&&(input.pattern==='[0-9]{6,64}'?pasted.length<6||pasted.length>64||/[^0-9]/.test(pasted):!isPin(pasted))){e.preventDefault();input.setCustomValidity(error);const status=form.querySelector('[role=status]');if(status)status.textContent=error}}});document.querySelectorAll('[data-show]').forEach(b=>b.onclick=()=>{const input=$('#'+b.dataset.show),show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'隠す':'表示';b.setAttribute('aria-pressed',String(show));if($('#'+b.dataset.show+'Again'))$('#'+b.dataset.show+'Again').type=input.type});form.onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const b=form.querySelector('[type=submit]');b.disabled=true;form.querySelector('[role=status]').textContent='確認・保存しています…';const guard=()=>{if(ticket!==epoch||!form.isConnected)throw Error('画面が変わりました。もう一度操作してください。')};try{await fn(guard)}catch(e){const out=form.querySelector('[role=status]');if(out?.isConnected)out.textContent=e.message;else message(e)}finally{busy=false;if(b.isConnected)b.disabled=false}}}
 const iconPicker=p=>Object.entries(iconGroups).map(([name,list])=>`<details ${list.includes(p?.icon||'🌱')?'open':''}><summary>${name}</summary><div class="iconPicker">${list.map(i=>`<button type="button" data-sec-icon="${esc(i)}" aria-pressed="${i===(p?.icon||'🌱')}" class="${i===(p?.icon||'🌱')?'selected':''}">${i}</button>`).join('')}</div></details>`).join('');
