 function login(id){state.current=id;const p=state.players.find(p=>p.id===id);if(!p)return;authenticated=null;playerChosen=false;teacher=null;epoch++;if(!security().players[id]){setupNeeded();return}modal(`<h2>パスワードを入力</h2><p>${esc(p.icon)} ${esc(p.name)}</p><form id="playerLogin">${passwordFields('loginPassword','本人用パスワード')}<button type="submit" class="primary wide">このプレイヤーで遊ぶ</button><p role="status" aria-live="polite"></p></form><p class="note">忘れたときは先生に再設定してもらってください。</p>`);if(security().players[id]?.policy==='digits4-10')$('#loginPassword').inputMode='numeric';runForm('playerLogin',async guard=>{const entered=$('#loginPassword').value,version=await check('player:'+id,entered);guard();childActivity=Date.now();authenticated={id,version};playerChosen=true;state.current=id;save();$('#modal').close();navigate(home);if(hasNameEmoji(p.name))toast('名前に絵文字が含まれています。プロフィールから名前を変更してください。')})}
